      .retire_instr_o ()
  );

  int errors = 0, checks = 0;
  logic [2:0] idle, got, mask;
  bit         saw_req;
  int e, b;

  task automatic do_reset;
    rst_n = 0;
    tb_boot_addr_i = '0;
    tb_fetch_enable_i = '1;
    tb_instr_gnt_i = '1;
    tb_instr_rvalid_i = '1;
    tb_instr_rdata_i = '0;
    tb_instr_err_i = '0;
    tb_data_gnt_i = '1;
    tb_data_rvalid_i = '1;
    tb_data_rdata_i = '0;
    tb_data_err_i = '0;
    tb_irq_soft_i = '0;
    tb_irq_timer_i = '0;
    tb_irq_ext_i = '0;
