  initial begin
    do_reset();
    idle = u_dut.state_q;
    // Compare only the bits a flip-flop actually drives.  yosys
    // declares the state wire at its RTL width and optimises constant
    // bits away, so a four-bit declaration can have three flops and one
    // permanently floating bit -- and comparing that bit makes every
    // encoding look like a failure.
    mask = '0;
    for (b = 0; b < 3; b++)
      if (idle[b] === 1'b0 || idle[b] === 1'b1) mask[b] = 1'b1;
    $display("[fsm-cdriscv_core] idle=%b driven=%b", idle, mask);

    for (e = 0; e < 8; e++) begin
      do_reset();
      force u_dut.state_q = 3'(e);
      @(posedge clk);
      #1ns;
      release u_dut.state_q;
      repeat (8) @(posedge clk);
      checks++;
      got = u_dut.state_q;
      // Every value of the driven bits is a legal state here --
      // ST_RUN, ST_WAIT_LSU, ST_WAIT_MD and ST_SLEEP use all four --
      // so "settled somewhere legal" is satisfied by construction and
      // says nothing.  The two checks that do say something are that
      // the state is defined, and that the core is still fetching
      // afterwards rather than wedged.
      if (((got ^ got) & mask) !== '0) begin
        $display("[fsm-cdriscv_core] FAIL: encoding %0d left the state X (%b)", e, got);
